/* steamprofiler.org - every publisher and every developer this site has read.

   Not a selection. Every company named in a storefront catalogue the site has
   already fetched is here, on the axis it was named on, with the games that
   were filed under it. A house with one game gets an entry exactly like a
   house with a hundred and fifty, because which of those is worth a screen is
   not a judgement this file makes.

   That also fixes what the shelves are and are not. They are what this site
   has read of the store, not the store: an app enters `apps` when somebody's
   library brings it in, so a house's shelf grows as the crawl does, and a
   game nobody who came here owns is not on it yet. The screens say so with a
   count rather than implying the list is the company's catalogue.

   Two axes and not one with a flag, because they are two different questions:
   Valve published Garry's Mod and Facepunch made it, so it is on the first
   shelf and not on the second.

   `apps` holds appids and the names live once in HOUSE_GAMES, because a game
   appears under its publisher and again under its developer and there is no
   reason to spell it twice. `flagship` is the most-reviewed game on the shelf
   and the newest one where nothing has a review total; it is used for the
   picture behind the tile and nothing else. There is no colour in this table -
   houses.js derives one from the slug, so adding a house is data and never a
   palette decision.

   `year` is the year Steam publishes for that app. A game Steam gives no date
   for keeps `null` and the screen bands it separately. Types other than
   `game` and anything still marked coming soon are left out.

   Generated from the site's own store cache - see tools in the repo history.
   Nothing here is executed and nothing here reads the DOM: it is a list. */

